#!/usr/bin/env bash
# Build a tiny local stand-in for nexaflow:<bucket>/main/x86_64 used by the
# apk-publish-index dry-run test. Regenerated on the runner so the repository
# stores a reviewable script instead of opaque binary apks.
#
# usage: generate.sh <pool-dir> <signing-key-path>
set -euo pipefail

pool="${1:?usage: generate.sh <pool-dir> <signing-key-path>}"
key="${2:?usage: generate.sh <pool-dir> <signing-key-path>}"

rm -rf "$pool"
mkdir -p "$pool"

# melange index parses .PKGINFO from each archive, so a printf placeholder is
# not enough: emit a minimal but structurally valid APK v3 (gzip tar with a
# control entry first).
make_apk() {
  local name="$1" origin="$2" out="$3"
  local dir="$pool/.build-$name"
  mkdir -p "$dir"
  cat > "$dir/.PKGINFO" <<EOF
# Generated by melange
pkgname = $name
pkgver = 20261020-r3
arch = x86_64
size = 8
origin = $origin
pkgdesc = fixture $name for apk-publish-index dry run
url =
commit = unknown
maintainer = nexaflow
builddate = 0
license = MPL-2.0 AND MIT
EOF
  printf 'fixture\n' > "$dir/fixture.txt"
  ( cd "$dir" && tar czf "$out" .PKGINFO fixture.txt )
  rm -rf "$dir"
}

make_apk ca-certificates ca-certificates "$pool/ca-certificates-20261020-r3.apk"
make_apk ca-certificates-bundle ca-certificates "$pool/ca-certificates-bundle-20261020-r3.apk"

# A previously published index carrying only one of the two apks. The action's
# --merge --source path must preserve that entry and add the other one.
melange index --signing-key "$key" -o "$pool/APKINDEX.tar.gz" \
  "$pool/ca-certificates-bundle-20261020-r3.apk"

echo "generate.sh: pool=$pool"
ls -l "$pool"
